local s=Game:GetProperty('JAC_JAPAN_START_STATE'); if s==nil then error('no start state recorded (JAC_Japan_StartState.lua)') end; local sb=Game:GetProperty('JAC_JAPAN_START_BUILDINGS'); if sb==nil then error('no start buildings recorded (JAC_Japan_StartState.lua)') end; local S={}; for id,vals in string.gmatch(s,'(%d+)=([%d,%-]+)') do local t={}; for v in string.gmatch(vals,'%-?%d+') do t[#t+1]=tonumber(v) end; S[tonumber(id)]=t end; local SB={}; for id,list in string.gmatch(sb,'(%d+):([^;]*)') do local t={}; for k,v in string.gmatch(list,'([%w_]+)=(%d+)') do t[k]=tonumber(v) end; SB[tonumber(id)]=t end; local out={'START'}; local bad={}; local names={'cities','pop','units','districts','walls','improvements'}; for i=0,21 do local leader=PlayerConfigurations[i]:GetLeaderTypeName(); local e=E[leader]; local got=S[i]; if not got or not e then error('missing player '..i..' '..tostring(leader)) end; if got[8]~=got[1] then bad[#bad+1]=leader..' ungarrisoned cities '..(got[1]-got[8]) end; if got[9]>0 then bad[#bad+1]=leader..' stacked plots '..got[9] end; for k=1,6 do if got[k]~=e[k] then bad[#bad+1]=leader..' '..names[k]..' '..got[k]..' expected '..e[k] end end; if got[7]<e[7] then bad[#bad+1]=leader..' gold '..got[7]..' expected >= '..e[7] end; local eb,gb=EB[leader] or {},SB[i] or {}; for k,v in pairs(eb) do if (gb[k] or 0)~=v then bad[#bad+1]=leader..' '..k..' '..(gb[k] or 0)..' expected '..v end end; for k,v in pairs(gb) do if eb[k]==nil then bad[#bad+1]=leader..' '..k..' '..v..' expected 0' end end; out[#out+1]=leader:gsub('LEADER_JAC_','')..' '..table.concat(got,'/',1,7) end; if #bad>0 then error(table.concat(bad,'; ')) end; return table.concat(out,'; ')